import { getTableConfig, type PgTable } from "drizzle-orm/pg-core";
import type { Client } from "pg";
import * as schema from "../../src/db/schema";

// The objects and metadata the committed migrations are allowed to leave in the test database. Anything
// else found there stops the destructive reset before it changes anything.
//
// Tables, columns, indexes, constraints and foreign keys are derived from src/db/schema.ts. Objects that
// only exist in SQL migrations or are generated by PostgreSQL are listed here by hand: when a migration
// adds such an object, add it to MANUAL_OBJECTS in the same change; when it adds or changes a column
// default, update EXPECTED_DEFAULTS.
//
// Checked: schemas, extensions, relations (all kinds), columns, constraints, triggers, functions, types,
// policies, table rules, extended statistics, publications and publication membership, event triggers,
// comments, privileges (table, sequence, column, function and drizzle-schema ACLs, default ACLs) and
// column defaults. NOT checked: column types, nullability, the definitions behind the names of indexes,
// constraints and triggers, function bodies, owners, row-level-security flags, storage options, security
// labels, and anything in a schema other than public and drizzle (other schemas are refused outright).
// This is a guard against mistakes, not a complete database diff.

const SCHEMA = "public";
const MIGRATION_SCHEMA = "drizzle";
const MIGRATION_TABLE = "__drizzle_migrations";

