// src/db/schema.ts exports only tables; a non-table export would fail the type check here.
const tables: PgTable[] = Object.values(schema);

// Identifiers come only from the committed schema and the constants in this file, never from input.
const quote = (name: string) => `"${name.replace(/"/g, '""')}"`;
const qualified = (schemaName: string, name: string) => `${quote(schemaName)}.${quote(name)}`;

const MANAGED_TABLES = tables.map((t) => {
  const config = getTableConfig(t);
  return qualified(config.schema ?? SCHEMA, config.name);
});
// Functions created by SQL migrations; dropped after their tables.
const MANAGED_FUNCTIONS = ["stock_movements_reject_change", "user_access_revoke_sessions", "append_only_reject_change", "guest_checkout_submissions_guard", "user_access_audit"];

/**
 * The destructive part of the test reset: every name is schema-qualified, every drop is RESTRICT (a
 * dependent object nobody listed makes PostgreSQL refuse instead of being dropped), and nothing else
 * (no other schema, no TRUNCATE, no CASCADE) is touched. Run only after `unexpectedObjects` is empty.
 */
export const DROP_MANAGED_STATEMENTS: string[] = [
  `drop table if exists ${MANAGED_TABLES.join(", ")} restrict;`,
  `drop function if exists ${MANAGED_FUNCTIONS.map((f) => `${qualified(SCHEMA, f)}()`).join(", ")} restrict;`,
  `drop table if exists ${qualified(MIGRATION_SCHEMA, MIGRATION_TABLE)} restrict;`,
  `drop schema if exists ${quote(MIGRATION_SCHEMA)} restrict;`,
];

export function expectedObjects(): Set<string> {
  const expected = new Set(MANUAL_OBJECTS);
  for (const table of tables) {
    const config = getTableConfig(table);
    const name = config.name;
    expected.add(`relation:${SCHEMA}.${name}:r`);
    for (const column of config.columns) {
      expected.add(`column:${SCHEMA}.${name}.${column.name}`);
      if (column.primary) {
        expected.add(`constraint:${SCHEMA}.${name}.${name}_pkey`);
        expected.add(`relation:${SCHEMA}.${name}_pkey:i`);
      }
      // A column-level .unique("name") is not in config.uniqueConstraints; PostgreSQL backs it with an index.
      if (column.isUnique && column.uniqueName) {
        expected.add(`constraint:${SCHEMA}.${name}.${column.uniqueName}`);
        expected.add(`relation:${SCHEMA}.${column.uniqueName}:i`);
      }
    }
    // A composite primary key (primaryKey({ name, columns })) is in config.primaryKeys, not on the columns.
    for (const pk of config.primaryKeys) {
      expected.add(`constraint:${SCHEMA}.${name}.${pk.getName()}`);
      expected.add(`relation:${SCHEMA}.${pk.getName()}:i`);
    }
    for (const index of config.indexes) expected.add(`relation:${SCHEMA}.${index.config.name}:i`);
    for (const check of config.checks) expected.add(`constraint:${SCHEMA}.${name}.${check.name}`);
    for (const fk of config.foreignKeys) expected.add(`constraint:${SCHEMA}.${name}.${fk.getName()}`);
    for (const unique of config.uniqueConstraints) {
      // PostgreSQL backs each unique constraint with an index of the same name.
      expected.add(`constraint:${SCHEMA}.${name}.${unique.name}`);
      expected.add(`relation:${SCHEMA}.${unique.name}:i`);
    }
  }
  return expected;
}

// True when an ACL differs from PostgreSQL's default for that kind of object. Entries are compared as a
// sorted set: after a GRANT and a REVOKE the same privileges can be stored in a different order.
const aclDiffers = (acl: string, defaultAcl: string) =>
  `(select string_agg(a::text, ',' order by a::text) from unnest(${acl}) a) is distinct from ` +
  `(select string_agg(a::text, ',' order by a::text) from unnest(${defaultAcl}) a)`;

// Everything that lives in the two managed schemas, plus anything that exists outside them.
// NOT NULL constraints (contype 'n', PostgreSQL 18) are not listed: the columns are.
const ACTUAL_OBJECTS_SQL = `
  select 'schema:' || nspname as object from pg_namespace
   where nspname not like 'pg\\_%' and nspname not in ('information_schema', 'public')
  union all
  select 'extension:' || extname from pg_extension where extname <> 'plpgsql'
  union all
  select 'relation:' || n.nspname || '.' || c.relname || ':' || c.relkind::text
    from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname in ('public', 'drizzle')
  union all
  select 'column:' || n.nspname || '.' || c.relname || '.' || a.attname
    from pg_attribute a join pg_class c on c.oid = a.attrelid join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public', 'drizzle') and a.attnum > 0 and not a.attisdropped and c.relkind in ('r', 'p', 'v', 'm', 'f')
  union all
  select 'constraint:' || n.nspname || '.' || c.relname || '.' || k.conname
    from pg_constraint k join pg_class c on c.oid = k.conrelid join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public', 'drizzle') and k.contype in ('c', 'u', 'f', 'p', 'x')
  union all
  select 'trigger:' || n.nspname || '.' || c.relname || '.' || t.tgname
    from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public', 'drizzle') and not t.tgisinternal
  union all
  select 'function:' || n.nspname || '.' || p.proname
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'drizzle')
  union all
  select 'type:' || n.nspname || '.' || t.typname
    from pg_type t join pg_namespace n on n.oid = t.typnamespace
   where n.nspname in ('public', 'drizzle') and t.typtype in ('e', 'd', 'r', 'm')
  union all
  select 'policy:' || n.nspname || '.' || c.relname || '.' || p.polname
    from pg_policy p join pg_class c on c.oid = p.polrelid join pg_namespace n on n.oid = c.relnamespace
  union all
  select 'rule:' || n.nspname || '.' || c.relname || '.' || r.rulename
    from pg_rewrite r join pg_class c on c.oid = r.ev_class join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public', 'drizzle') and c.relkind in ('r', 'p')
  union all
  select 'statistics:' || n.nspname || '.' || s.stxname
    from pg_statistic_ext s join pg_namespace n on n.oid = s.stxnamespace
  union all
  select 'publication:' || pubname from pg_publication
  union all
  select 'publication_table:' || n.nspname || '.' || c.relname || ':' || p.pubname
    from pg_publication_rel r join pg_publication p on p.oid = r.prpubid
    join pg_class c on c.oid = r.prrelid join pg_namespace n on n.oid = c.relnamespace
  union all
  select 'default_acl:' || d.defaclrole::regrole::text || ':' || d.defaclobjtype::text from pg_default_acl d
  -- Privileges. A missing ACL means PostgreSQL's default, and so does an ACL equal to acldefault().
  union all
  select 'acl:' || n.nspname || '.' || c.relname
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public', 'drizzle') and c.relkind in ('r', 'p', 'v', 'm', 'f', 'S') and c.relacl is not null
     and ${aclDiffers("c.relacl", `acldefault(case when c.relkind = 'S' then 's'::"char" else 'r'::"char" end, c.relowner)`)}
  union all
  select 'column_acl:' || n.nspname || '.' || c.relname || '.' || a.attname
    from pg_attribute a join pg_class c on c.oid = a.attrelid join pg_namespace n on n.oid = c.relnamespace
   where n.nspname in ('public', 'drizzle') and a.attnum > 0 and not a.attisdropped
     and a.attacl is not null and cardinality(a.attacl) > 0
  union all
  select 'function_acl:' || n.nspname || '.' || p.proname
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname in ('public', 'drizzle') and p.proacl is not null
     and ${aclDiffers("p.proacl", "acldefault('f', p.proowner)")}
  union all
  select 'schema_acl:' || n.nspname from pg_namespace n
   where n.nspname = 'drizzle' and n.nspacl is not null and ${aclDiffers("n.nspacl", "acldefault('n', n.nspowner)")}
  -- Comments on everything the reset drops (the comment on the public schema is PostgreSQL's own).
  union all
  select 'comment:relation:' || n.nspname || '.' || c.relname
    from pg_description d join pg_class c on c.oid = d.objoid join pg_namespace n on n.oid = c.relnamespace
   where d.classoid = 'pg_class'::regclass and d.objsubid = 0 and n.nspname in ('public', 'drizzle')
  union all
  select 'comment:column:' || n.nspname || '.' || c.relname || '.' || a.attname
    from pg_description d join pg_class c on c.oid = d.objoid join pg_namespace n on n.oid = c.relnamespace
    join pg_attribute a on a.attrelid = c.oid and a.attnum = d.objsubid
   where d.classoid = 'pg_class'::regclass and d.objsubid > 0 and n.nspname in ('public', 'drizzle')
  union all
  select 'comment:constraint:' || n.nspname || '.' || c.relname || '.' || k.conname
    from pg_description d join pg_constraint k on k.oid = d.objoid
    join pg_class c on c.oid = k.conrelid join pg_namespace n on n.oid = c.relnamespace
   where d.classoid = 'pg_constraint'::regclass and n.nspname in ('public', 'drizzle')
  union all
  select 'comment:trigger:' || n.nspname || '.' || c.relname || '.' || t.tgname
    from pg_description d join pg_trigger t on t.oid = d.objoid
    join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace
   where d.classoid = 'pg_trigger'::regclass and n.nspname in ('public', 'drizzle')
  union all
  select 'comment:function:' || n.nspname || '.' || p.proname
    from pg_description d join pg_proc p on p.oid = d.objoid join pg_namespace n on n.oid = p.pronamespace
   where d.classoid = 'pg_proc'::regclass and n.nspname in ('public', 'drizzle')
  union all
  select 'comment:schema:' || n.nspname
    from pg_description d join pg_namespace n on n.oid = d.objoid
   where d.classoid = 'pg_namespace'::regclass and n.nspname = 'drizzle'
`;

// Column defaults are compared in JavaScript so that an error names only the column, never the expression.
export const DEFAULTS_SQL = `
  select n.nspname as schema, c.relname as rel, a.attname as col, pg_get_expr(d.adbin, d.adrelid) as expr
    from pg_attribute a join pg_class c on c.oid = a.attrelid join pg_namespace n on n.oid = c.relnamespace
    left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
   where n.nspname in ('public', 'drizzle') and c.relkind in ('r', 'p') and a.attnum > 0 and not a.attisdropped
`;

// Event triggers are database-wide and need a superuser to create, so tests cannot plant one; the
// handling of this query's result is covered with a stubbed result instead.
export const EVENT_TRIGGERS_SQL = "select evtname from pg_event_trigger";

type DefaultRow = { schema: string; rel: string; col: string; expr: string | null };

/** Columns whose default differs from EXPECTED_DEFAULTS (added, changed or dropped). Names only, no expressions. */
export function defaultDeviations(rows: DefaultRow[]): string[] {
  return rows
    .filter((r) => r.expr !== (EXPECTED_DEFAULTS[`${r.schema}.${r.rel}.${r.col}`] ?? null))
    .map((r) => `default:${r.schema}.${r.rel}.${r.col}`);
}


/**
 * Objects and metadata in the connected database that the migrations do not create (identifiers only, never
 * values). Empty means every object kind listed at the top of this file is accounted for in the public and
 * drizzle schemas and no other schema exists, so nothing of those kinds can depend on a managed object. It
 * does not mean the database equals the migrations in every respect (see the list of what is not checked).
 */
export async function unexpectedObjects(conn: Pick<Client, "query">): Promise<string[]> {
  const objects = await conn.query<{ object: string }>(ACTUAL_OBJECTS_SQL);
  const defaults = await conn.query<DefaultRow>(DEFAULTS_SQL);
  const eventTriggers = await conn.query<{ evtname: string }>(EVENT_TRIGGERS_SQL);
  const expected = expectedObjects();
  return [
    ...objects.rows.map((r) => r.object).filter((o) => !expected.has(o)),
    ...defaultDeviations(defaults.rows),
    ...eventTriggers.rows.map((r) => `event_trigger:${r.evtname}`),
  ].sort();
}
